window.MG_LAZY_DATA["data/lazy/resources/security-v26-037-5f07e9d6418fa6a3.json"]={sha256:"5f07e9d6418fa6a3f373223607cab2ff33124ef4b37713a4ff8777471702a9f6",value:{"sources":[{"id":"v26-case-88dd19746c477a96","url":"https://d3fend.mitre.org/","title":"MITRE D3FEND Matrix","titleEn":"MITRE D3FEND Matrix","publisher":"MITRE","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-037","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-037","related":[{"id":"security-v26-038","referenceUrls":["https://attack.mitre.org/resources/"],"title":"MITRE ATT&CK：行為假說與可驗證偵測範圍","titleEn":"MITRE ATT&CK: behavior hypotheses and verifiable detection scope","why":"用兩課的可觀察驗收條件比較模型邊界：75%與87.5%由明示矩陣重算，所有已驗證邊可重播，圖譜名稱未被當作產品背書。 交付六動作/四物件的關係圖、24條證據索引及三條剩餘缺口。","whyEn":"Compare model boundaries using observable acceptance criteria: Recompute 75% and 87.5% from the explicit matrix, replay every validated edge and do not present ontology terminology as product endorsement. Deliver a six-action/four-artifact graph, 24 evidence indices and the three remaining gaps.","difference":"只選與虛構學院環境相關的20個行為假說，以合成日誌描述可觀察條件；逐項列資料來源、偵測邏輯、測試與盲點，不重演真實入侵。","differenceEn":"Select 20 behavior hypotheses relevant to a fictional academy and express observable conditions through synthetic logs; list source, detection logic, test and blind spot without reenacting intrusion.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["本地關係矩陣覆蓋=已以fixture驗證的指定關係/預先定義關係；知識圖譜存在一條邊不代表你的產品已有效實作。 教學驗收定義24條需驗證關係，其中18條有可重現證據。 18/24×100=75%；再驗證3條後21/24×100=87.5%。","受測覆蓋率=已有正例與正常負例通過的假說/事先選定假說；不能將本地分母與完整ATT&CK技術總數混用。 教學範圍20個假說，其中12個完成正負例驗證，其餘8個未完成。 12/20×100=60%；補完4個後16/20×100=80%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Local matrix coverage is fixture-validated relationships divided by predefined relationships; an ontology edge does not prove effective implementation in a product. The teaching acceptance plan defines 24 relationships, of which 18 have reproducible evidence. 18/24×100=75%; validating three more gives 21/24×100=87.5%.","Tested coverage equals hypotheses passing positive and normal-negative fixtures divided by preselected hypotheses; do not mix the local denominator with the full ATT&CK catalog. The teaching scope contains 20 hypotheses, 12 validated with positive and negative fixtures and 8 unfinished. 12/20×100=60%; completing four more yields 16/20×100=80%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-047","referenceUrls":["https://source.android.com/docs/security/features/verifiedboot"],"title":"Android Verified Boot：信任鏈與回滾索引","titleEn":"Android Verified Boot: trust chains and rollback indices","why":"用兩課的可觀察驗收條件比較模型邊界：75%與87.5%由明示矩陣重算，所有已驗證邊可重播，圖譜名稱未被當作產品背書。 交付六動作/四物件的關係圖、24條證據索引及三條剩餘缺口。","whyEn":"Compare model boundaries using observable acceptance criteria: Recompute 75% and 87.5% from the explicit matrix, replay every validated edge and do not present ontology terminology as product endorsement. Deliver a six-action/four-artifact graph, 24 evidence indices and the three remaining gaps.","difference":"用合成bootloader、vbmeta與分割區清單畫驗證鏈；分開標示簽章有效、裝置鎖定狀態與rollback index，不對真實手機解鎖或刷機。","differenceEn":"Map bootloader, vbmeta and partitions from synthetic records; distinguish signature validity, device lock state and rollback index without unlocking or flashing a real phone.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["本地關係矩陣覆蓋=已以fixture驗證的指定關係/預先定義關係；知識圖譜存在一條邊不代表你的產品已有效實作。 教學驗收定義24條需驗證關係，其中18條有可重現證據。 18/24×100=75%；再驗證3條後21/24×100=87.5%。","教學回滾判定要求候選index≥已記錄最低index，且簽章與其他驗證通過；差值是索引間距，不是安全強度或版本年齡。 已儲存最低index=7，候選index=10；兩者均為同一rollback位置的整數。 候選高出10−7=3個索引單位；候選改8時高出1個；候選6則應拒絕。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Local matrix coverage is fixture-validated relationships divided by predefined relationships; an ontology edge does not prove effective implementation in a product. The teaching acceptance plan defines 24 relationships, of which 18 have reproducible evidence. 18/24×100=75%; validating three more gives 21/24×100=87.5%.","The teaching rollback rule requires candidate index≥stored minimum plus valid signatures and other checks; index difference is neither strength nor version age. Stored minimum index is 7 and candidate is 10, both integers for the same rollback location. Candidate margin is 10−7=3 index units; candidate 8 gives one, while candidate 6 must be rejected.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-1f1b26ebfa9e00d6","url":"https://attack.mitre.org/resources/","title":"MITRE ATT&CK: Get Started","titleEn":"MITRE ATT&CK: Get Started","publisher":"MITRE","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-aca8ed3696682883","url":"https://source.android.com/docs/security/features/verifiedboot","title":"Android Verified Boot","titleEn":"Android Verified Boot","publisher":"Android Open Source Project","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
